import fs from "node:fs/promises";
import path from "node:path";
import type { SupabaseClient } from "@supabase/supabase-js";

export const STORAGE_BUCKET = "academic-files";

/**
 * Storage keys are always generated by the server (never derived from user
 * input): "<area>/<uuid>/<uuid>.<ext>". Anything else is rejected, which rules
 * out path traversal regardless of backend.
 */
const KEY_RE = /^(submissions|materials)\/[0-9a-f-]{36}\/[0-9a-f-]{36}\.(pdf|docx|pptx|txt)$/;

export function assertSafeKey(key: string): void {
  if (!KEY_RE.test(key)) throw new Error("Invalid storage key");
}

export interface FileStorage {
  readonly kind: "local" | "supabase";
  put(key: string, data: Uint8Array, contentType: string): Promise<void>;
  get(key: string): Promise<Uint8Array>;
  remove(keys: string[]): Promise<void>;
  /** Short-lived signed URL, or null when the backend streams through the app instead. */
  signedUrl(key: string, expiresInSeconds: number, downloadName: string | null): Promise<string | null>;
}

/** DEMO MODE ONLY: files on the server's local disk, outside the public web root. */
export class LocalFileStorage implements FileStorage {
  readonly kind = "local" as const;
  constructor(private root: string) {}

  private resolve(key: string): string {
    assertSafeKey(key);
    const full = path.resolve(this.root, key);
    if (!full.startsWith(path.resolve(this.root) + path.sep)) throw new Error("Invalid storage key");
    return full;
  }

  async put(key: string, data: Uint8Array): Promise<void> {
    const full = this.resolve(key);
    await fs.mkdir(path.dirname(full), { recursive: true });
    await fs.writeFile(full, data, { mode: 0o600, flag: "wx" });
  }

  async get(key: string): Promise<Uint8Array> {
    return new Uint8Array(await fs.readFile(this.resolve(key)));
  }

  async remove(keys: string[]): Promise<void> {
    for (const key of keys) await fs.rm(this.resolve(key), { force: true });
  }

  async signedUrl(): Promise<string | null> {
    return null;
  }
}

/** Private Supabase Storage bucket; access is additionally restricted by storage RLS policies. */
export class SupabaseFileStorage implements FileStorage {
  readonly kind = "supabase" as const;
  constructor(private client: SupabaseClient) {}

  async put(key: string, data: Uint8Array, contentType: string): Promise<void> {
    assertSafeKey(key);
    const { error } = await this.client.storage.from(STORAGE_BUCKET).upload(key, data, { contentType, upsert: false });
    if (error) throw new Error("Upload to storage failed");
  }

  async get(key: string): Promise<Uint8Array> {
    assertSafeKey(key);
    const { data, error } = await this.client.storage.from(STORAGE_BUCKET).download(key);
    if (error || !data) throw new Error("File not found in storage");
    return new Uint8Array(await data.arrayBuffer());
  }

  async remove(keys: string[]): Promise<void> {
    if (keys.length === 0) return;
    keys.forEach(assertSafeKey);
    const { error } = await this.client.storage.from(STORAGE_BUCKET).remove(keys);
    if (error) throw new Error("Storage delete failed");
  }

  async signedUrl(key: string, expiresInSeconds: number, downloadName: string | null): Promise<string | null> {
    assertSafeKey(key);
    const { data, error } = await this.client.storage
      .from(STORAGE_BUCKET)
      .createSignedUrl(key, expiresInSeconds, downloadName ? { download: downloadName } : undefined);
    if (error || !data) throw new Error("Could not sign URL");
    return data.signedUrl;
  }
}

/** In-memory storage for automated tests. */
export class MemoryFileStorage implements FileStorage {
  readonly kind = "local" as const;
  files = new Map<string, Uint8Array>();
  async put(key: string, data: Uint8Array) {
    assertSafeKey(key);
    if (this.files.has(key)) throw new Error("exists");
    this.files.set(key, data);
  }
  async get(key: string) {
    assertSafeKey(key);
    const f = this.files.get(key);
    if (!f) throw new Error("File not found in storage");
    return f;
  }
  async remove(keys: string[]) {
    keys.forEach((k) => this.files.delete(k));
  }
  async signedUrl() {
    return null;
  }
}
